'use strict';

// MODULES //

var tape = require( 'tape' );
var isArray = require( '@stdlib/assert/is-array' );
var goodManifest = require( '@stdlib/_tools/manifest-json/schema/test/fixtures/good.json' );
var missingConfs = require( '@stdlib/_tools/manifest-json/schema/test/fixtures/missing_confs.json' );
var missingFields = require( '@stdlib/_tools/manifest-json/schema/test/fixtures/missing_fields.json' );
var missingOptions = require( '@stdlib/_tools/manifest-json/schema/test/fixtures/missing_options.json' );
var badConfs = require( '@stdlib/_tools/manifest-json/schema/test/fixtures/bad_confs1.json' );
var badFields = require( '@stdlib/_tools/manifest-json/schema/test/fixtures/bad_fields1.json' );
var isValid = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof isValid, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `true` if provided a valid `manifest.json`', function test( t ) {
	var bool = isValid( goodManifest );

	t.strictEqual( bool, true, 'returns expected value' );
	t.strictEqual( isValid.errors, null, 'errors property is `null`' );
	t.end();
});

tape( 'the function returns `false` if provided an invalid `manifest.json` (missing configurations)', function test( t ) {
	var bool = isValid( missingConfs );

	t.strictEqual( bool, false, 'returns expected value' );
	t.strictEqual( isArray( isValid.errors ), true, 'errors property is an array' );
	t.end();
});

tape( 'the function returns `false` if provided an invalid `manifest.json` (missing fields)', function test( t ) {
	var bool = isValid( missingFields );

	t.strictEqual( bool, false, 'returns expected value' );
	t.strictEqual( isArray( isValid.errors ), true, 'errors property is an array' );
	t.end();
});

tape( 'the function returns `false` if provided an invalid `manifest.json` (missing options)', function test( t ) {
	var bool = isValid( missingOptions );

	t.strictEqual( bool, false, 'returns expected value' );
	t.strictEqual( isArray( isValid.errors ), true, 'errors property is an array' );
	t.end();
});

tape( 'the function returns `false` if provided an invalid `manifest.json` (bad configurations)', function test( t ) {
	var bool = isValid( badConfs );

	t.strictEqual( bool, false, 'returns expected value' );
	t.strictEqual( isArray( isValid.errors ), true, 'errors property is an array' );
	t.end();
});

tape( 'the function returns `false` if provided an invalid `manifest.json` (bad fields)', function test( t ) {
	var bool = isValid( badFields );

	t.strictEqual( bool, false, 'returns expected value' );
	t.strictEqual( isArray( isValid.errors ), true, 'errors property is an array' );
	t.end();
});

tape( 'the function returns `false` if provided an invalid object', function test( t ) {
	var manifest;
	var bool;

	manifest = {
		'beep': 'boop'
	};
	bool = isValid( manifest );

	t.strictEqual( bool, false, 'returns expected value' );
	t.strictEqual( isArray( isValid.errors ), true, 'errors property is an array' );
	t.end();
});
